import{z as s,x as B,o as r,c as d,q as i,j as A,D as n,d as E,s as l,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"Krugman 新贸易理论","description":"","frontmatter":{"title":"Krugman 新贸易理论","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/krugman-new-trade.md","filePath":"econ/krugman-new-trade.md","lastUpdated":1791063341000}'),m={name:"econ/krugman-new-trade.md"};function p(u,a,C,g,D,c){const t=B("Mermaid");return r(),d("div",null,[a[2]||(a[2]=i('<h1 id="krugman-新贸易理论" tabindex="-1">Krugman 新贸易理论 <a class="header-anchor" href="#krugman-新贸易理论" aria-label="Permalink to &quot;Krugman 新贸易理论&quot;">​</a></h1><div class="epigraph"><p>禀赋与技术都相同，只要规模报酬递增和爱多样性，两国仍会互相出口差异产品；产业内贸易不再是对 HO 的尴尬残差。</p><footer>—— Krugman, Increasing Returns, Monopolistic Competition, and International Trade, JIE 1979；Krugman, Scale Economies, Product Differentiation, and the Pattern of Trade, AER 1980</footer></div><p><a href="/econ/stolper-samuelson">上一课</a>在 \\(2\\times2\\) 里把价格切给要素。本课缺口是：战后增长最快的是<strong>产业内</strong>贸易（德国汽车换法国汽车），HO 解释弱。Krugman 用垄断竞争与规模报酬。Melitz 下一课再把企业异质叠上去；本课先钉对称企业、品种、本国市场效应。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Dixit–Stiglitz 偏好：爱多样性，每种品种垄断竞争，固定成本加不变边际成本。封闭时品种数与企业规模由自由进入与市场大小决定。开放（冰山运输成本或零成本）：市场变大，每国消费者可及品种增加，每家企业产量摊薄固定成本。即便两国完全相同，也会双向出口差异产品。缺口不是否认李嘉图与 HO，而是：它们解释产业间；本课解释产业内。贸易增益来自品种与规模，不只来自机会成本差。</p><p><span class="marginnote">1980 年本国市场效应：有运输成本时，需求更大的国家成为该行业净出口国——规模报酬把生产拉向大市场。这是对 HO「只看供给禀赋」的补充。</span></p><p><span class="marginnote">直觉类比：两国各造一款车时，谁也摊不满流水线；市场合并后每款车卖得多，固定成本摊薄、单价下降。同时消费者在本国车之外多出外国车可选——哪怕两国一模一样，交换不同款车仍然双赢，这就是产业内贸易为什么不需要任何「禀赋差异」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对称企业，一种生产要素（劳动）。均衡：价格加成由替代弹性定，零利润定产量，劳动市场出清定品种数。开放：外国品种进入，本国部分企业退出或每家规模变，福利是实际工资加品种。贸易成本下降的比较静态：更多产业内贸易、更低加成（若垄断竞争强度变）、更多品种。</p>',9)),(r(),A(o,null,{default:n(()=>[l(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20IRS%5B%22%E8%A7%84%E6%A8%A1%E6%8A%A5%E9%85%AC%20%2B%20%E5%9B%BA%E5%AE%9A%E6%88%90%E6%9C%AC%22%5D%20--%3E%20MC%5B%22%E5%9E%84%E6%96%AD%E7%AB%9E%E4%BA%89%22%5D%0A%20%20LOVE%5B%22%E7%88%B1%E5%A4%9A%E6%A0%B7%E6%80%A7%22%5D%20--%3E%20VAR%5B%22%E5%93%81%E7%A7%8D%22%5D%0A%20%20MC%20--%3E%20IIT%5B%22%E4%BA%A7%E4%B8%9A%E5%86%85%E5%8F%8C%E5%90%91%E8%B4%B8%E6%98%93%22%5D%0A%20%20VAR%20--%3E%20IIT%0A%20%20HM%5B%22%E5%A4%A7%E5%B8%82%E5%9C%BA%22%5D%20--%3E%20HME%5B%22%E6%9C%AC%E5%9B%BD%E5%B8%82%E5%9C%BA%E6%95%88%E5%BA%94%3A%20%E5%87%80%E5%87%BA%E5%8F%A3%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[E("与计量结构课：这套 CES 需求与"),e("a",{href:"/econ/discrete-choice"},"离散选择"),E("同源（McFadden / Anderson–de Palma–Thisse）。BLP 是随机系数现场版；Krugman 是对称解析版。本课不估汽车，只给机制。")],-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"术语翻译：「价格加成」就是成本之上再加一个百分比当售价，比例由品种间的替代弹性定——越可替代，加成越薄。数字实例：替代弹性为 5 时加成率约 \\(1/(5-1)=25\\%\\)，边际成本 80 的车标价 100；替代弹性升到 9，加成就薄到 12.5%。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"机制是市场扩大摊固定成本，加上消费者对外国品种的评价。没有要素密集差，也可以有贸易。分配：对称模型里劳动是唯一要素，没有 SS 的 \\(w\\) 对 \\(r\\)；增益较均匀。一旦把技能或特定要素放回来，产业内贸易仍可与分配冲突并存——不要用 Krugman 取消 SS。",-1)),(r(),A(o,null,{default:n(()=>[l(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20OPEN%5B%22%E5%BC%80%E6%94%BE%3A%20%E4%B8%A4%E5%B8%82%E5%9C%BA%E5%90%88%E5%B9%B6%22%5D%20--%3E%20BIG%5B%22%E6%B6%88%E8%B4%B9%E8%80%85%E5%8F%AF%E5%8F%8A%E5%93%81%E7%A7%8D%E5%A2%9E%E5%8A%A0%22%5D%0A%20%20OPEN%20--%3E%20SCALE%5B%22%E6%AF%8F%E5%AE%B6%E4%BC%81%E4%B8%9A%E4%BA%A7%E9%87%8F%E6%91%8A%E8%96%84%E5%9B%BA%E5%AE%9A%E6%88%90%E6%9C%AC%22%5D%0A%20%20EXIT%5B%22%E9%83%A8%E5%88%86%E6%9C%AC%E5%9B%BD%E4%BC%81%E4%B8%9A%E9%80%80%E5%87%BA%22%5D%20--%3E%20SCALE%0A%20%20SCALE%20--%3E%20ACCOST%5B%22%E5%B9%B3%E5%9D%87%E6%88%90%E6%9C%AC%E4%B8%8B%E9%99%8D%22%5D%0A%20%20ACCOST%20--%3E%20PDOWN%5B%22%E5%8A%A0%E6%88%90%E4%BB%B7%E6%A0%BC%E6%9B%B4%E4%BD%8E%22%5D%0A%20%20BIG%20--%3E%20WEL%5B%22%E7%A6%8F%E5%88%A9%3A%20%E5%AE%9E%E9%99%85%E5%B7%A5%E8%B5%84%20%2B%20%E5%93%81%E7%A7%8D%22%5D%0A%20%20PDOWN%20--%3E%20WEL%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<p>经济地理（Krugman 1991）把同一套 IRS 放进空间集聚，本课只标：贸易成本与 IRS 一起可以产生核心–边缘，不是本课必须解完。</p><p><span class="marginnote">新贸易理论不是「新」在否定比较优势，而是比较优势的来源从禀赋/技术扩到规模与偏好。Helpman–Krugman 把 HO 与产业内写进同一本书。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>对称企业解释不了「为什么只有一部分企业出口」——下一课 Melitz。引力下一课把双边流量写成规模与距离，可以兼容本课 CES。关税福利：小国在本课有品种增益对关税收入的权衡，最优关税后课再写。不要把 1979/1980 模型当成已经包含异质企业或全球价值链。</p><p><span class="marginnote">常见误区：以为新贸易理论「推翻」了比较优势。实际上两者分工：李嘉图与 HO 管产业间（酒换布），Krugman 管产业内（德国车换法国车）。也别拿「只有部分企业出口」的事实来反驳本课——对称模型本来就人人出口，选择效应是 Melitz 叠上去的。</span></p><p>后课默认：相同国家之间可以因 IRS 与多样性而产业内贸易；本国市场效应让大需求国净出口该行业。SS 分配在只有一种劳动时淡出，多要素时仍在。Melitz 把选择效应叠在同一套 CES 上。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>IRS + 爱多样性 ⇒ 产业内贸易，即使禀赋相同。</li><li>增益来自品种与规模，不只来自比较成本。</li><li>本国市场效应：大需求 + 贸易成本 ⇒ 净出口。</li><li>对称企业：所有企业都出口（零贸易成本时）；异质留给 Melitz。</li><li>出处：Krugman, <em>JIE</em> 1979、<em>AER</em> 1980；Dixit–Stiglitz；Helpman and Krugman。</li></ul>',8))])}const f=s(m,[["render",p]]);export{h as __pageData,f as default};
